EMPTY, DELETED = object(), object()

class ProbingTable:
    def __init__(self, capacity=8):
        self.slots = [EMPTY] * capacity           # each slot: EMPTY, DELETED or (key, value).

    def _probe(self, key):
        i = hash(key) % len(self.slots)
        for _ in range(len(self.slots)):
            yield i
            i = (i + 1) % len(self.slots)          # linear probing, wraps around.

    def find(self, key):
        for i in self._probe(key):
            s = self.slots[i]
            if s is EMPTY:
                return None                      # a real gap: key can't be further on.
            if s is not DELETED and s[0] == key:   # DELETED or other key: keep going.
                return s[1]
        return None                              # checked every slot.

    def delete(self, key):
        for i in self._probe(key):
            s = self.slots[i]
            if s is EMPTY:
                return False
            if s is not DELETED and s[0] == key:
                self.slots[i] = DELETED          # tombstone, not EMPTY.
                return True
        return False
```

| Strategy | Insert | Find stops at | Delete |
|---|---|---|---|
| chaining. | append to bucket list. | end of that list. | remove from the list. |
| linear probing. | first EMPTY or DELETED slot. | the key or an EMPTY slot. | leave a tombstone. |

